// M6.3 Stripe in the database [ADM-PAY-01, -03, -06, -07, ADM-INV-10, ADM-INV-17, JOB-HOOK-01..03, POR-06; m6.3 run file A, B and I]: 0065 adds columns and an index
// only, 0066 recreates exactly its triggers (0064 unchanged, both regenerated byte for byte by the triggers test), the provider lists equal the schema's, manual and
// Razorpay shapes unchanged, the Stripe payment shape (USD, card or other, charges 0, the INR fee columns), a Stripe payment never rejected or withdrawn and never
// confirmed by the system (`gateway_auto` stays Razorpay's), live or stale → failed, the new columns frozen, the rule table's SQL twin (with `payment_pending`),
// the checkout create with the online maximum, a Stripe payment confirmed and allocated with its INR facts, the stale-live sweep read and the EXPLAIN plans. Raw SQL and
// the real statement builders; all names and amounts are invented test data.
import { env } from "cloudflare:workers";
import { uuidv7 } from "@techaust/core";
import { ONLINE_RULES, payableOnline } from "@techaust/core/online-pay";
import { describe, expect, it } from "vitest";
import {
  checkoutCreateStatement,
  checkoutFailStatement,
  checkoutLiveStatement,
  type GatewayPaymentArgs,
  onlinePayableSql,
  recordGatewayPaymentStatements,
  STALE_LIVE_CHECKOUTS_SQL,
  STALE_LIVE_LIMIT,
} from "../src/gateway.ts";
import { GATEWAY_AUTO_SQL } from "../src/issue.ts";
import { guardSql } from "../src/log.ts";
import { GATEWAY_PROVIDERS, PAYMENT_PROVIDERS } from "../src/schema/payments.ts";
import { ONLINE_RULES_SQL } from "../src/sql-rules.ts";
import {
  GATEWAY_PROVIDERS_0066,
  PAYMENT_FROZEN_0064,
  PAYMENT_FROZEN_0066,
  PAYMENT_PROVIDERS_0066,
  STRIPE_RECREATED_0066,
} from "../src/triggers.ts";
import { mkClientRow, mkContact, mkMember, next } from "./billing-helpers.ts";
import { all, first, rejects, run } from "./helpers.ts";

const T = 1_850_000_000_000;
let clock = T;
const tick = () => (clock += 10);
const db = () => env.DB;

const session = () => `cs_test_a1${uuidv7().replaceAll("-", "")}${"B".repeat(30)}`;

/** An issued document written straight in, in a currency, with its balance. */
async function mkDoc(
  clientId: string,
  o: { type?: string; currency?: "INR" | "USD"; balance?: number; status?: string; parentId?: string } = {},
): Promise<string> {
  const id = uuidv7();
  const n = next();
  const type = o.type ?? "export_invoice";
  const currency = o.currency ?? "USD";
  // A debit note names its invoice (`documents_note_parent_required_insert`): one of the client's own, in the document's currency.
  const parentId =
    o.parentId ??
    (type === "debit_note"
      ? await mkDoc(clientId, { type: currency === "USD" ? "export_invoice" : "tax_invoice", currency })
      : null);
  await run(
    `INSERT INTO documents (id, type, status, client_id, currency, series, fy, number, number_display, frozen_at, issue_date, due_date, subtotal_minor, taxable_minor, total_minor, balance_minor, content_sha256, updated_at, voided_at, void_reason, parent_id)
     VALUES (?1, ?2, ?3, ?4, ?5, 'stp-s', '9999', ?6, ?7, 1000, '2026-10-28', '2026-11-04', 50000, 50000, 50000, ?8, ?9, 7000, ?10, ?11, ?12)`,
    id,
    type,
    o.status ?? "issued",
    clientId,
    currency,
    n,
    `S/${n}`,
    o.balance ?? 50_000,
    "h".repeat(64),
    o.status === "void" ? 5 : null,
    o.status === "void" ? "x" : null,
    parentId,
  );
  return id;
}

/** A Stripe checkout made through the real create statement, then live with a session id and Checkout URL. */
async function stripeCheckout(
  documentId: string,
  clientId: string,
  contactId: string,
  o: { amount?: number; floor?: number; max?: number | null; live?: boolean; expiresAt?: number } = {},
): Promise<{ id: string; sessionId: string; changes: number }> {
  const id = uuidv7();
  const now = tick();
  const r = await checkoutCreateStatement(db(), {
    id,
    provider: "stripe",
    documentId,
    clientId,
    source: "portal",
    contactId,
    docTokenId: null,
    createdBy: null,
    amountMinor: o.amount ?? 50_000,
    floorMinor: o.floor ?? 10_000,
    maxMinor: o.max === undefined ? 2_500_000 : o.max,
    expiresAt: o.expiresAt ?? now + 3_600_000,
    now,
  }).run();
  const sessionId = session();
  if (r.meta.changes === 1 && o.live !== false)
    await checkoutLiveStatement(db(), {
      id,
      providerLinkId: sessionId,
      shortUrl: `https://checkout.stripe.com/c/pay/${sessionId}`,
      expiresAt: o.expiresAt ?? now + 3_600_000,
      now: tick(),
    }).run();
  return { id, sessionId, changes: r.meta.changes };
}

async function world(o: { type?: string; balance?: number } = {}) {
  const owner = await mkMember("owner");
  const clientId = await mkClientRow({ currency: "USD" });
  const contactId = await mkContact(clientId);
  const documentId = await mkDoc(clientId, { type: o.type, balance: o.balance });
  return { owner, clientId, contactId, documentId };
}

type StripeRow = Partial<{
  id: string;
  status: string;
  currency: string;
  kind: string;
  mode: string | null;
  ref: string | null;
  charges: number;
  feeTax: number | null;
  inr: number | null;
  fee: number | null;
  feeTaxInr: number | null;
  ppid: string | null;
  recordedBy: string | null;
  requested: string | null;
  provider: string;
}>;

/** A Stripe payment row written straight in (confirmed by the gateway unless told otherwise). */
async function stpPay(clientId: string, checkoutId: string, o: StripeRow = {}): Promise<string> {
  const pi = `pi_3Q${uuidv7().replaceAll("-", "").slice(-16)}`;
  const id = o.id ?? `stp_${pi}`;
  const status = o.status ?? "confirmed";
  await run(
    `INSERT INTO payments (id, client_id, kind, provider, status, currency, amount_minor, charges_minor, received_on, mode, reference_norm, requested_allocations,
       recorded_by, recorded_at, verified_by, verified_at, provider_payment_id, checkout_id, fee_tax_minor, refetched_at, inr_received_minor, gateway_fee_inr_minor, gateway_fee_tax_inr_minor)
     VALUES (?1, ?2, ?3, ?4, ?5, ?6, 50000, ?7, '2026-10-30', ?8, ?9, ?10, ?11, ?12, NULL, ?13, ?14, ?15, ?16, ?12, ?17, ?18, ?19)`,
    id,
    clientId,
    o.kind ?? "payment",
    o.provider ?? "stripe",
    status,
    o.currency ?? "USD",
    o.charges ?? 0,
    o.mode === undefined ? "card" : o.mode,
    o.ref === undefined ? pi.replace("_", "-").toUpperCase() : o.ref,
    o.requested ?? null,
    o.recordedBy ?? null,
    T,
    status === "confirmed" ? T : null,
    o.ppid === undefined ? pi : o.ppid,
    checkoutId,
    o.feeTax === undefined ? null : o.feeTax,
    o.inr === undefined ? 41_500_00 : o.inr,
    o.fee === undefined ? 1_800_00 : o.fee,
    o.feeTaxInr === undefined ? 274_58 : o.feeTaxInr,
  );
  return id;
}

// ---- migrations ------------------------------------------------------------------------------------------------------------------------------------------

describe("0065 and 0066: no rebuild, the pinned lists [run file A]", () => {
  it("0065 only adds the two payment columns and the proof-awaited index", () => {
    const m = env.TEST_MIGRATIONS.find((x) => x.name === "0065_stripe.sql");
    const qs = (m?.queries ?? []).map((x) => x.replace(/^(\s|--> statement-breakpoint)+/, "").trim());
    expect(qs).toHaveLength(3);
    expect(qs[0]).toMatch(/^ALTER TABLE `payments` ADD `gateway_fee_inr_minor` integer/);
    expect(qs[1]).toMatch(/^ALTER TABLE `payments` ADD `gateway_fee_tax_inr_minor` integer/);
    expect(qs[2]).toMatch(/^CREATE INDEX `payments_proof_awaited` ON `payments`/);
    expect(qs.join("\n")).not.toMatch(/DROP|__new_|INSERT INTO|CHECK/);
  });

  it("0066 drops exactly the triggers it creates again, and touches nothing else", () => {
    const m = env.TEST_MIGRATIONS.find((x) => x.name === "0066_stripe_triggers.sql");
    const text = (m?.queries ?? []).join("\n");
    expect(text).not.toMatch(/DROP TABLE|DROP INDEX|__new_|ALTER TABLE|INSERT INTO/);
    const dropped = [...text.matchAll(/DROP TRIGGER `([a-z_]+)`/g)].map((x) => x[1]);
    const created = [...text.matchAll(/CREATE TRIGGER `([a-z_]+)`/g)].map((x) => x[1]);
    expect(dropped).toEqual([...STRIPE_RECREATED_0066]);
    expect(created).toEqual([...STRIPE_RECREATED_0066]);
  });

  it("the lists of 0066 are the schema's lists today; the frozen list is 0064's and the two INR fee columns", () => {
    expect(PAYMENT_PROVIDERS_0066).toEqual(PAYMENT_PROVIDERS);
    expect(GATEWAY_PROVIDERS_0066).toEqual(GATEWAY_PROVIDERS);
    expect(PAYMENT_FROZEN_0066).toEqual([
      ...PAYMENT_FROZEN_0064,
      "gateway_fee_inr_minor",
      "gateway_fee_tax_inr_minor",
    ]);
  });

  it("the columns are there, nullable, with no default", async () => {
    const cols = await all<{ name: string; notnull: number; dflt_value: unknown }>(
      "PRAGMA table_info(payments)",
    );
    for (const name of ["gateway_fee_inr_minor", "gateway_fee_tax_inr_minor"])
      expect(cols.find((c) => c.name === name)).toMatchObject({ notnull: 0, dflt_value: null });
  });

  it("GATEWAY_AUTO_SQL names Razorpay explicitly (a Stripe payment never issues a tax invoice by itself: Q1 A)", () => {
    expect(GATEWAY_AUTO_SQL).toContain("gp.provider = 'razorpay'");
  });
});

// ---- the payment shape ------------------------------------------------------------------------------------------------------------------------------------

describe("payments_gateway_shape of 0066 [L10, L1]", () => {
  it("a confirmed or pending Stripe payment lands, with or without its INR facts", async () => {
    const { clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    await stpPay(clientId, co.id);
    await stpPay(clientId, co.id, { status: "pending_verification", mode: "other" });
    await stpPay(clientId, co.id, { inr: null, fee: null, feeTaxInr: null });
    await stpPay(clientId, co.id, { fee: 0, feeTaxInr: 0 });
    // A 255-character payment intent id; the reference stays at most 60 (core `stripeReferenceNorm`).
    await stpPay(clientId, co.id, {
      ppid: `pi_${"Z9_".repeat(84)}`,
      ref: `PI-${"Z9-".repeat(13)}Z-0123456789AB`,
    });
  });

  it.each([
    ["not USD", { currency: "INR", inr: null }],
    ["a bank mode", { mode: "neft" }],
    ["UPI", { mode: "upi" }],
    ["no mode", { mode: null }],
    ["no reference", { ref: null }],
    ["charges in the USD column", { charges: 5 }],
    ["a fee tax in the USD column", { feeTax: 1 }],
    ["a negative INR fee", { fee: -1, feeTaxInr: null }],
    ["a fee tax above the fee", { fee: 100, feeTaxInr: 101 }],
    ["a fee tax with no fee", { fee: null, feeTaxInr: 5 }],
    ["a negative fee tax", { fee: 100, feeTaxInr: -1 }],
    ["TDS", { kind: "tds" }],
    ["a gateway id too long", { ppid: `pi_${"a".repeat(253)}` }],
  ] as const)("refuses %s", async (_what, o) => {
    const { clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    await rejects(stpPay(clientId, co.id, o as StripeRow), /payments_gateway_shape|payments_values_insert/);
  });

  it("the insert state holds for Stripe too: no member, its gateway id, checkout and re-fetch", async () => {
    const { owner, clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    await rejects(stpPay(clientId, co.id, { recordedBy: owner }), /payments_insert_state/);
    await rejects(stpPay(clientId, co.id, { ppid: null }), /payments_insert_state/);
  });

  it("manual and Razorpay rows may not carry the INR fee columns; their 0064 shapes are otherwise unchanged", async () => {
    const owner = await mkMember("owner");
    const inrClient = await mkClientRow();
    const contactId = await mkContact(inrClient);
    const manual = (extra: string) =>
      run(
        `INSERT INTO payments (id, client_id, kind, provider, status, currency, amount_minor, received_on, mode, recorded_by, recorded_at, verified_by, verified_at${extra ? `, ${extra}` : ""})
         VALUES (?1, ?2, 'payment', 'manual', 'confirmed', 'INR', 1000, '2026-10-28', 'neft', ?3, ?4, ?3, ?4${extra ? ", 5" : ""})`,
        uuidv7(),
        inrClient,
        owner,
        T,
      );
    await manual("");
    await rejects(manual("gateway_fee_inr_minor"), /payments_gateway_shape/);
    await rejects(manual("gateway_fee_tax_inr_minor"), /payments_gateway_shape/);
    // Razorpay: an INR tax invoice's link; its fee in the INR columns is refused, its own columns land as in 0064.
    const inv = await mkDoc(inrClient, { type: "tax_invoice", currency: "INR", balance: 118_000 });
    const co = uuidv7();
    await run(
      `INSERT INTO checkout_sessions (id, provider, document_id, client_id, contact_id, source, currency, amount_minor, status, expires_at, created_at, updated_at)
       VALUES (?1, 'razorpay', ?2, ?3, ?4, 'portal', 'INR', 118000, 'creating', ?5, ?6, ?6)`,
      co,
      inv,
      inrClient,
      contactId,
      T + 86_400_000,
      T,
    );
    const rzp = (cols: string, vals: string) =>
      run(
        `INSERT INTO payments (id, client_id, kind, provider, status, currency, amount_minor, charges_minor, received_on, mode, reference_norm, recorded_at, verified_at, provider_payment_id, checkout_id, refetched_at${cols})
         VALUES (?1, ?2, 'payment', 'razorpay', 'confirmed', 'INR', 118000, 2360, '2026-10-28', 'upi', ?3, ?4, ?4, ?5, ?6, ?4${vals})`,
        `rzp_${uuidv7()}`,
        inrClient,
        `PAY-${next()}`,
        T,
        `pay_${next()}`,
        co,
      );
    await rzp("", "");
    await rejects(rzp(", gateway_fee_inr_minor", ", 5"), /payments_gateway_shape/);
    await rejects(rzp(", gateway_fee_tax_inr_minor", ", 5"), /payments_gateway_shape/);
  });
});

// ---- moves -------------------------------------------------------------------------------------------------------------------------------------------------

describe("payments_status_flow and payments_fixed of 0066 [L5, L7, Q1 A]", () => {
  it("a Stripe payment is never rejected or withdrawn, even by the Owner; a pending one is confirmed by the Owner", async () => {
    const { owner, clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    const pending = await stpPay(clientId, co.id, { status: "pending_verification" });
    await rejects(
      run(
        "UPDATE payments SET status = 'rejected', verified_by = ?2, verified_at = ?3, decision_note = 'no' WHERE id = ?1",
        pending,
        owner,
        T,
      ),
      /payments_status_flow/,
    );
    const confirmed = await stpPay(clientId, co.id);
    await rejects(
      run(
        "UPDATE payments SET status = 'withdrawn', withdrawn_by = ?2, withdrawn_at = ?3, withdraw_reason = 'x' WHERE id = ?1",
        confirmed,
        owner,
        T,
      ),
      /payments_status_flow/,
    );
    await run(
      "UPDATE payments SET status = 'confirmed', verified_by = ?2, verified_at = ?3 WHERE id = ?1",
      pending,
      owner,
      T,
    );
    expect(await first("SELECT status, verified_by FROM payments WHERE id = ?", pending)).toEqual({
      status: "confirmed",
      verified_by: owner,
    });
  });

  it("the system's own confirm (`gateway_auto`) is Razorpay's only: a Stripe payment with a matching receipt and no member is refused", async () => {
    const { owner, clientId, contactId } = await world();
    const proforma = await mkDoc(clientId, { type: "proforma" });
    const co = await stripeCheckout(proforma, clientId, contactId);
    const p = await stpPay(clientId, co.id, {
      status: "pending_verification",
      requested: JSON.stringify([{ documentId: proforma, amountMinor: 50_000 }]),
      ref: "PI-3QSYSTEM",
    });
    const invoice = await mkDoc(clientId, { type: "export_invoice", parentId: proforma });
    const receipt = uuidv7();
    await run(
      `INSERT INTO advance_receipts (id, proforma_id, invoice_id, client_id, currency, amount_minor, received_on, reference_norm, created_by, created_at)
       VALUES (?1, ?2, ?3, ?4, 'USD', 50000, '2026-10-30', 'PI-3QSYSTEM', ?5, ?6)`,
      receipt,
      proforma,
      invoice,
      clientId,
      owner,
      T,
    );
    // Everything 0064's system path asked for (its own receipt, written at the confirm's instant, no member): still refused for Stripe.
    await rejects(
      run(
        "UPDATE payments SET status = 'confirmed', verified_at = ?2, advance_receipt_id = ?3 WHERE id = ?1",
        p,
        T,
        receipt,
      ),
      /payments_status_flow/,
    );
    // Without any receipt the system path is refused all the more.
    await rejects(
      run("UPDATE payments SET status = 'confirmed', verified_at = ?2 WHERE id = ?1", p, T),
      /payments_status_flow/,
    );
    // The trigger's own text names Razorpay alone for that path.
    const trig = await first<{ sql: string }>(
      "SELECT sql FROM sqlite_master WHERE type = 'trigger' AND name = 'payments_status_flow'",
    );
    expect(trig?.sql).toContain(
      "OLD.provider IN ('razorpay') AND NEW.status = 'confirmed' AND NEW.verified_by IS NULL",
    );
  });

  it("the INR fee columns never change after the insert (payments_fixed)", async () => {
    const { clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    const p = await stpPay(clientId, co.id);
    for (const col of ["gateway_fee_inr_minor", "gateway_fee_tax_inr_minor", "inr_received_minor"])
      await rejects(run(`UPDATE payments SET ${col} = 1 WHERE id = ?1`, p), /payments_fixed/);
    await rejects(run("UPDATE payments SET gateway_fee_inr_minor = NULL WHERE id = ?1", p), /payments_fixed/);
  });
});

describe("checkout_sessions of 0066 [L6, run file A]", () => {
  it("a Stripe checkout is a known provider; live or stale may fail (an asynchronous card payment), creating as before", async () => {
    const { clientId, contactId } = await world();
    const live = await stripeCheckout(await mkDoc(clientId), clientId, contactId);
    expect((await checkoutFailStatement(db(), { id: live.id, now: tick() }).run()).meta.changes).toBe(0);
    expect(
      (await checkoutFailStatement(db(), { id: live.id, now: tick(), from: "open" }).run()).meta.changes,
    ).toBe(1);
    expect(await first("SELECT status FROM checkout_sessions WHERE id = ?", live.id)).toEqual({
      status: "failed",
    });
    const stale = await stripeCheckout(await mkDoc(clientId), clientId, contactId);
    await run(
      "UPDATE checkout_sessions SET status = 'stale', updated_at = updated_at + 1 WHERE id = ?1",
      stale.id,
    );
    expect(
      (await checkoutFailStatement(db(), { id: stale.id, now: tick(), from: "open" }).run()).meta.changes,
    ).toBe(1);
    // A failed checkout goes nowhere.
    await rejects(
      run(
        "UPDATE checkout_sessions SET status = 'live', updated_at = updated_at + 1 WHERE id = ?1",
        stale.id,
      ),
      /checkout_sessions_status_flow/,
    );
    // creating → failed is the create path's; the open path never ends a creating row.
    const creating = await stripeCheckout(await mkDoc(clientId), clientId, contactId, { live: false });
    expect(
      (await checkoutFailStatement(db(), { id: creating.id, now: tick(), from: "open" }).run()).meta.changes,
    ).toBe(0);
    expect((await checkoutFailStatement(db(), { id: creating.id, now: tick() }).run()).meta.changes).toBe(1);
    // An unknown provider is still refused.
    await rejects(
      run(
        `INSERT INTO checkout_sessions (id, provider, document_id, client_id, contact_id, source, currency, amount_minor, status, expires_at, created_at, updated_at)
         VALUES (?1, 'paypal', ?2, ?3, ?4, 'portal', 'USD', 100, 'creating', ?5, ?5, ?5)`,
        uuidv7(),
        await mkDoc(clientId),
        clientId,
        contactId,
        T,
      ),
      /checkout_sessions_values_insert/,
    );
  });

  it("webhook events and review items take the Stripe provider", async () => {
    const ev = uuidv7();
    await run(
      "INSERT INTO webhook_events (id, provider, event_id, event_type, received_at, status, facts) VALUES (?1, 'stripe', ?2, 'checkout.session.completed', ?3, 'received', '{}')",
      ev,
      `evt_${ev.slice(-12)}`,
      T,
    );
    await run(
      "INSERT INTO review_items (id, source, provider, kind, status, webhook_event_id, created_at) VALUES (?1, 'webhook', 'stripe', 'unknown_link', 'open', ?2, ?3)",
      uuidv7(),
      ev,
      T,
    );
    await rejects(
      run(
        "INSERT INTO webhook_events (id, provider, event_id, event_type, received_at, status) VALUES (?1, 'paypal', 'x', 'y', ?2, 'received')",
        uuidv7(),
        T,
      ),
      /webhook_events_values_insert/,
    );
  });
});

// ---- the rule table in SQL ------------------------------------------------------------------------------------------------------------------------------------

describe("onlinePayableSql is the twin of core payableOnline, per provider [L14, X1]", () => {
  it("the SQL table equals core's", () => {
    expect(JSON.parse(JSON.stringify(ONLINE_RULES_SQL))).toEqual(JSON.parse(JSON.stringify(ONLINE_RULES)));
  });

  const cases = [
    [{}, {}, false],
    [{ type: "debit_note" }, {}, false],
    [{ type: "proforma", balance: 12_345 }, {}, false],
    [{ type: "proforma", status: "paid" }, {}, false],
    [{ type: "tax_invoice", currency: "INR", balance: 118_000 }, { domestic: true }, false],
    [{ type: "tax_invoice", currency: "INR", balance: 118_050 }, { domestic: true }, false],
    [{ type: "proforma", currency: "INR", balance: 118_050 }, { domestic: true }, false],
    // (A USD client's INR invoice and a domestic client's export invoice cannot exist: `documents_invoice_currency`, `documents_invoice_type_client`.)
    [{ type: "proforma", currency: "INR", balance: 118_000 }, { domestic: true }, false],
    [{ type: "debit_note", currency: "INR", balance: 118_000 }, { domestic: true }, false],
    [{ status: "void" }, {}, false],
    [{ balance: 49 }, {}, false],
    [{ balance: 50 }, {}, false],
    [{ balance: 0, status: "paid" }, {}, false],
    [{}, { anonymised: true }, false],
    [{ type: "proforma" }, {}, true],
    [{ type: "proforma", currency: "INR", balance: 118_000 }, { domestic: true }, true],
  ] as const;
  for (const provider of ["razorpay", "stripe"] as const)
    it.each(cases)(`${provider}: doc %j, client %j, pending %s`, async (d, k, pending) => {
      const usd = !("domestic" in k);
      const clientId = await mkClientRow({ currency: usd ? "USD" : "INR" });
      if ("anonymised" in k) await run("UPDATE clients SET anonymised_at = 5 WHERE id = ?1", clientId);
      const documentId = await mkDoc(clientId, {
        type: d.type,
        currency: "currency" in d ? d.currency : usd ? "USD" : "INR",
        balance: "balance" in d ? d.balance : 50_000,
        status: "status" in d ? d.status : undefined,
      });
      if (pending) {
        // A gateway payment waiting on the document, through one of its checkouts, with the requested allocation naming it.
        const contactId = await mkContact(clientId);
        const co = uuidv7();
        await run(
          `INSERT INTO checkout_sessions (id, provider, document_id, client_id, contact_id, source, currency, amount_minor, status, expires_at, created_at, updated_at)
           VALUES (?1, ?2, ?3, ?4, ?5, 'portal', ?6, 100, 'creating', ?7, ?7, ?7)`,
          co,
          usd ? "stripe" : "razorpay",
          documentId,
          clientId,
          contactId,
          usd ? "USD" : "INR",
          T,
        );
        await run(
          "UPDATE checkout_sessions SET status = 'live', provider_link_id = ?2, short_url = 'https://checkout.stripe.com/c/pay/x', updated_at = ?3 WHERE id = ?1",
          co,
          `link_${co}`,
          T + 1,
        );
        await run(
          `INSERT INTO payments (id, client_id, kind, provider, status, currency, amount_minor, charges_minor, received_on, mode, reference_norm, requested_allocations,
             recorded_at, provider_payment_id, checkout_id, refetched_at)
           VALUES (?1, ?2, 'payment', ?3, 'pending_verification', ?4, 100, 0, '2026-10-30', ?5, ?6, ?7, ?8, ?9, ?10, ?8)`,
          `x_${co}`,
          clientId,
          usd ? "stripe" : "razorpay",
          usd ? "USD" : "INR",
          usd ? "card" : "upi",
          `REF-${next()}`,
          JSON.stringify([{ documentId, amountMinor: 100 }]),
          T,
          `pi_${next()}`,
          co,
        );
      }
      const row = await first<{
        ok: number;
        type: string;
        currency: string;
        status: string;
        balance_minor: number;
        country: string;
        gst_status: string;
        anon: number;
      }>(
        `SELECT ${onlinePayableSql("d", "k", provider)} AS ok, d.type, d.currency, d.status, d.balance_minor, k.country, k.gst_status, k.anonymised_at IS NOT NULL AS anon
         FROM documents d JOIN clients k ON k.id = d.client_id WHERE d.id = ?`,
        documentId,
      );
      if (!row) throw new Error("row");
      const core = payableOnline(
        {
          type: row.type,
          currency: row.currency,
          frozen: true,
          status: row.status,
          withdrawn: false,
          balanceMinor: row.balance_minor,
          paymentPending: pending,
        },
        { country: row.country, gstStatus: row.gst_status, anonymised: row.anon === 1 },
        provider,
      );
      expect(row.ok === 1).toBe(core.ok);
      if (pending) expect(core).toMatchObject({ ok: false });
    });
});

// ---- the statements for Stripe ------------------------------------------------------------------------------------------------------------------------------

describe("checkoutCreateStatement for Stripe: the rule table and the online maximum [L1, L9, Q2 A]", () => {
  it("an overseas client's USD export invoice: created; above the maximum or below the floor: nothing", async () => {
    const { clientId, contactId } = await world();
    const big = await mkDoc(clientId, { balance: 9_000_000 });
    expect((await stripeCheckout(big, clientId, contactId, { amount: 2_500_001, live: false })).changes).toBe(
      0,
    );
    expect((await stripeCheckout(big, clientId, contactId, { amount: 9_999, live: false })).changes).toBe(0);
    // Cents are fine on Stripe (no whole-unit rule), and a null maximum is none.
    expect((await stripeCheckout(big, clientId, contactId, { amount: 2_500_001, max: null })).changes).toBe(
      1,
    );
    const proforma = await mkDoc(clientId, { type: "proforma", balance: 12_345 });
    expect((await stripeCheckout(proforma, clientId, contactId, { amount: 12_345 })).changes).toBe(1);
  });

  it("refuses a domestic client's INR invoice and a document with a payment waiting", async () => {
    const { clientId, contactId, documentId } = await world();
    const inr = await mkClientRow();
    const inrContact = await mkContact(inr);
    expect(
      (await stripeCheckout(await mkDoc(inr, { type: "tax_invoice", currency: "INR" }), inr, inrContact))
        .changes,
    ).toBe(0);
    // A pending payment through an earlier checkout, asking for this document: no second link (payment_pending).
    const first_ = await stripeCheckout(documentId, clientId, contactId);
    await stpPay(clientId, first_.id, {
      status: "pending_verification",
      requested: JSON.stringify([{ documentId, amountMinor: 50_000 }]),
    });
    await run(
      "UPDATE checkout_sessions SET status = 'stale', updated_at = updated_at + 1 WHERE id = ?1",
      first_.id,
    );
    expect((await stripeCheckout(documentId, clientId, contactId)).changes).toBe(0);
  });
});

const stripePayArgs = (
  w: { clientId: string; documentId: string; checkoutId: string },
  over: Partial<GatewayPaymentArgs> = {},
): GatewayPaymentArgs => {
  const pi = `pi_3Q${String(next()).padStart(10, "0")}`;
  const now = tick();
  return {
    provider: "stripe",
    providerPaymentId: pi,
    paymentId: `stp_${pi}`,
    checkoutId: w.checkoutId,
    clientId: w.clientId,
    documentId: w.documentId,
    webhookEventId: null,
    source: "refresh",
    status: "confirmed",
    amountMinor: 50_000,
    feeMinor: 0,
    feeTaxMinor: null,
    inrReceivedMinor: 41_500_00,
    gatewayFeeInrMinor: 1_800_00,
    gatewayFeeTaxInrMinor: 274_58,
    receivedOn: "2026-10-30",
    mode: "card",
    referenceNorm: pi.replace("_", "-").toUpperCase(),
    refetchedAt: now - 1,
    now,
    allocate: { allocationId: uuidv7(), overpaidReviewId: uuidv7(), facts: { linkId: "cs_x" } },
    requestedAllocations: null,
    checkoutPaid: true,
    staleOthers: true,
    event: null,
    bell: null,
    ...over,
  };
};

async function writePayment(a: GatewayPaymentArgs): Promise<boolean> {
  const auditId = uuidv7();
  const s = recordGatewayPaymentStatements(db(), a, guardSql({ auditId }));
  const audit = db()
    .prepare(
      "INSERT INTO audit_log (id, actor_type, actor_id, role, action, entity_type, entity_id) SELECT ?1, 'webhook', NULL, NULL, 'payment.gateway', 'payment', ?2 WHERE changes() > 0",
    )
    .bind(auditId, a.paymentId);
  const res = await db().batch([s.main, audit, ...s.side, ...s.last]);
  return res[1]?.meta.changes === 1;
}

describe("recordGatewayPaymentStatements for Stripe [ADM-PAY-03, -06, L10]", () => {
  it("a confirmed card payment on an export invoice: allocated, the invoice paid, the INR facts stored; a replay with a new id writes nothing", async () => {
    const { clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    const a = stripePayArgs({ clientId, documentId, checkoutId: co.id });
    expect(await writePayment(a)).toBe(true);
    expect(
      await first(
        "SELECT status, currency, charges_minor, fee_tax_minor, inr_received_minor, gateway_fee_inr_minor, gateway_fee_tax_inr_minor FROM payments WHERE id = ?",
        a.paymentId,
      ),
    ).toEqual({
      status: "confirmed",
      currency: "USD",
      charges_minor: 0,
      fee_tax_minor: null,
      inr_received_minor: 41_500_00,
      gateway_fee_inr_minor: 1_800_00,
      gateway_fee_tax_inr_minor: 274_58,
    });
    expect(await first("SELECT status, balance_minor FROM documents WHERE id = ?", documentId)).toEqual({
      status: "paid",
      balance_minor: 0,
    });
    expect(await first("SELECT status, paid_payment_id FROM checkout_sessions WHERE id = ?", co.id)).toEqual({
      status: "paid",
      paid_payment_id: a.paymentId,
    });
    // The same payment intent again (a replay with a new event id): no second row.
    expect(await writePayment({ ...a, paymentId: `stp_${a.providerPaymentId}`, now: tick() })).toBe(false);
    expect(await writePayment({ ...a, paymentId: `stp_other_${next()}`, now: tick() })).toBe(false);
  });

  it("a USD balance transaction leaves the INR columns NULL", async () => {
    const { clientId, contactId, documentId } = await world();
    const co = await stripeCheckout(documentId, clientId, contactId);
    const a = stripePayArgs(
      { clientId, documentId, checkoutId: co.id },
      { inrReceivedMinor: null, gatewayFeeInrMinor: null, gatewayFeeTaxInrMinor: null },
    );
    expect(await writePayment(a)).toBe(true);
    expect(
      await first(
        "SELECT inr_received_minor, gateway_fee_inr_minor, gateway_fee_tax_inr_minor FROM payments WHERE id = ?",
        a.paymentId,
      ),
    ).toEqual({ inr_received_minor: null, gateway_fee_inr_minor: null, gateway_fee_tax_inr_minor: null });
  });

  it("a confirmed Stripe payment is never put on a domestic client's INR invoice (the provider's row, not Razorpay's)", async () => {
    // A Stripe checkout row written straight in on a domestic INR tax invoice (the create statement would refuse it): the payment's main INSERT writes nothing.
    const clientId = await mkClientRow();
    const contactId = await mkContact(clientId);
    const documentId = await mkDoc(clientId, { type: "tax_invoice", currency: "INR", balance: 50_000 });
    const co = uuidv7();
    await run(
      `INSERT INTO checkout_sessions (id, provider, document_id, client_id, contact_id, source, currency, amount_minor, status, expires_at, created_at, updated_at)
       VALUES (?1, 'stripe', ?2, ?3, ?4, 'portal', 'INR', 50000, 'creating', ?5, ?6, ?6)`,
      co,
      documentId,
      clientId,
      contactId,
      T + 3_600_000,
      T,
    );
    await run(
      "UPDATE checkout_sessions SET status = 'live', provider_link_id = ?2, short_url = 'https://checkout.stripe.com/c/pay/x', updated_at = ?3 WHERE id = ?1",
      co,
      session(),
      T + 1,
    );
    expect(await writePayment(stripePayArgs({ clientId, documentId, checkoutId: co }))).toBe(false);
    expect(await first("SELECT count(*) AS n FROM payments WHERE checkout_id = ?", co)).toEqual({ n: 0 });
  });

  it("a USD proforma's payment waits pending with its requested allocation (Q1 A), and then the proforma is not payable again", async () => {
    const { clientId, contactId } = await world();
    const proforma = await mkDoc(clientId, { type: "proforma", balance: 50_000 });
    const co = await stripeCheckout(proforma, clientId, contactId);
    const a = stripePayArgs(
      { clientId, documentId: proforma, checkoutId: co.id },
      {
        status: "pending_verification",
        allocate: null,
        requestedAllocations: [{ documentId: proforma, amountMinor: 50_000 }],
      },
    );
    expect(await writePayment(a)).toBe(true);
    expect(
      await first(
        "SELECT status, requested_allocations IS NOT NULL AS req FROM payments WHERE id = ?",
        a.paymentId,
      ),
    ).toEqual({
      status: "pending_verification",
      req: 1,
    });
    const row = await first<{ ok: number }>(
      `SELECT ${onlinePayableSql("d", "k", "stripe")} AS ok FROM documents d JOIN clients k ON k.id = d.client_id WHERE d.id = ?`,
      proforma,
    );
    expect(row?.ok).toBe(0);
  });
});

// ---- the sweep's read and the plans --------------------------------------------------------------------------------------------------------------------------

describe("STALE_LIVE_CHECKOUTS_SQL and the new index [L6, L13, ADM-INV-17]", () => {
  it("live checkouts 15 minutes past their expiry, not refreshed since, at most 10", async () => {
    const { clientId, contactId } = await world();
    // Expiries far before every other test's (the file shares one database), so the oldest-first limit of 10 reaches these rows.
    const base = 1_000_000;
    const past = await stripeCheckout(await mkDoc(clientId), clientId, contactId, {
      expiresAt: base + 3_600_000,
    });
    const future = await stripeCheckout(await mkDoc(clientId), clientId, contactId, {
      expiresAt: base + 9 * 3_600_000,
    });
    const cutoff = base + 3_600_000 + 15 * 60_000 + 1;
    const ids = (await all<{ id: string }>(STALE_LIVE_CHECKOUTS_SQL, cutoff)).map((r) => r.id);
    expect(ids).toContain(past.id);
    expect(ids).not.toContain(future.id);
    await run("UPDATE checkout_sessions SET last_refresh_at = ?2 WHERE id = ?1", past.id, cutoff + 5);
    expect((await all<{ id: string }>(STALE_LIVE_CHECKOUTS_SQL, cutoff)).map((r) => r.id)).not.toContain(
      past.id,
    );
    expect(STALE_LIVE_CHECKOUTS_SQL).toContain(`LIMIT ${STALE_LIVE_LIMIT}`);
  });

  const plan = async (sql: string, ...binds: unknown[]) =>
    (await all<{ detail: string }>(`EXPLAIN QUERY PLAN ${sql}`, ...binds)).map((r) => r.detail).join("\n");

  it("the proof-awaited filter, the sweep and the pending check read through their indexes", async () => {
    expect(
      await plan(
        "SELECT id FROM payments WHERE provider IN ('stripe', 'paypal') AND proof_r2_key IS NULL AND status IN ('pending_verification', 'confirmed') AND received_on >= ?1 ORDER BY received_on, id LIMIT 51",
        "2026-10-01",
      ),
    ).toContain("payments_proof_awaited");
    expect(await plan(STALE_LIVE_CHECKOUTS_SQL, T)).toContain("checkout_sessions_open");
    const pendingPlan = await plan(
      `SELECT ${onlinePayableSql("d", "k", "stripe")} FROM documents d JOIN clients k ON k.id = d.client_id WHERE d.id = ?1`,
      "x",
    );
    expect(pendingPlan).toContain("checkout_sessions_document");
    expect(pendingPlan).toContain("payments_checkout");
  });
});
